import {
  barEnd,
  readoutRoomPx,
  walkRowReadoutParts
} from "./chunk-GWCWAQPL.js";
import {
  walkRows
} from "./chunk-KYCRK274.js";
import {
  backboneNodes,
  backbonePositions,
  overlapsWindow
} from "./chunk-DGIFVUAC.js";
import {
  ROW_HEIGHT_PX
} from "./chunk-CPMHA4W5.js";

// src/layout/walkRowLayout.ts
var READOUT_ROOM = 1.3;
function longestBar(walks) {
  return walks.rows.reduce(
    (most, row) => Math.max(most, barEnd(row)),
    barEnd(walks.reference)
  );
}
function readableReach(walks, fit) {
  const { widthPx } = fit;
  return [walks.reference, ...walks.rows].reduce((most, _, i) => {
    const { row, base, suffix } = walkRowReadoutParts(walks, i, fit.comparing);
    const room = readoutRoomPx(`${base}${suffix}`, fit.measure);
    return Math.max(
      most,
      barEnd(row) * widthPx / Math.max(widthPx - room, widthPx / 4)
    );
  }, 0);
}
function walkRowsExtent(walks, pitch = {
  rowPx: ROW_HEIGHT_PX,
  readouts: true
}, fit) {
  const readable = pitch.readouts && fit ? readableReach(walks, fit) : 0;
  return {
    maxX: walks.origin + Math.max(
      readable,
      longestBar(walks) * (pitch.readouts ? READOUT_ROOM : 1)
    ),
    maxY: walks.rows.length * pitch.rowPx
  };
}
function walkRowLabels(rows, layout, pitch) {
  if (!rows) {
    return layout?.rowLabels ?? [];
  }
  if (pitch && !pitch.labelled) {
    return [];
  }
  return [rows.reference, ...rows.rows].map((row, i) => ({
    label: row.label,
    y: i * (pitch?.rowPx ?? ROW_HEIGHT_PX)
  }));
}
function walkRowLayout(graph, region) {
  const walks = walkRows(graph, region);
  return walks && walkRowLayoutOf(graph, walks, region);
}
function walkRowLayoutOf(graph, walks, region) {
  const backbone = backboneNodes(graph);
  if (backbone.length === 0) {
    return void 0;
  }
  const overWindow = region ? backbone.filter((n) => overlapsWindow(n, region)) : backbone;
  const nodePositions = backbonePositions(
    overWindow.length > 0 ? overWindow : backbone
  );
  return {
    nodePositions,
    rowLabels: walkRowLabels(walks),
    referenceAxis: true,
    pixelRows: true,
    extent: walkRowsExtent(walks)
  };
}

export {
  READOUT_ROOM,
  longestBar,
  walkRowsExtent,
  walkRowLabels,
  walkRowLayout,
  walkRowLayoutOf
};
